from lib import *
recs=[
R(9226480,"Trempette végétalienne à la crème sure et à l'oignon",
"Une trempette crémeuse aux oignons caramélisés, VÉGANISÉE ! Elle est TELLEMENT bonne !",
"6 portions","1 portion",
["1 tasse de bouillon de légumes faible en sodium (divisé)","2 oignons jaunes moyens (en dés)","1.5 tasse de haricots blancs cannellini (cuits ou en conserve (environ une boîte de 15 onces))","3 cuillères à soupe de jus de citron (ou de vinaigre de cidre de pomme)","1 cuillère à soupe de tamari (ou de sauce soja si vous n'évitez pas le gluten)","3/4 cuillère à café de poudre d'ail","3/4 cuillère à café de poudre d'oignon","2-4 cuillères à soupe d'eau (selon la consistance désirée)","ciboulette hachée","assaisonnement pour bagel « everything »","croustilles de pita","croustilles de tortilla","craquelins"],
["Mettez l'oignon en dés avec ¼ tasse de bouillon dans une poêle en fonte ou une poêle antiadhésive et faites-le sauter à feu moyen-vif. Remuez de temps en temps et continuez d'ajouter environ ¼ tasse de bouillon à la fois, lorsque le bouillon précédent s'est complètement évaporé, pour éviter que les oignons collent. Poursuivez jusqu'à ce que les oignons soient dorés et caramélisés et que le bouillon soit entièrement utilisé. Cela prendra environ 15-20 minutes. Réservez une fois terminé.","Pendant ce temps, mettez tous les ingrédients de la crème sure dans un mélangeur haute vitesse, en commençant par 2 cuillères à soupe d'eau. Mélangez jusqu'à consistance parfaitement lisse et ajoutez de l'eau si vous préférez une consistance plus fluide. Goûtez pour le sel et ajoutez-en au besoin. (La sauce soja apporte un peu de salinité ; goûtez donc avant d'ajouter du sel.)","Transférez la crème sure végétalienne dans un bol, puis incorporez les oignons caramélisés. Réfrigérez au moins 1 heure, mais un peu plus longtemps est encore mieux. La trempette est meilleure froide, lorsque les saveurs ont eu le temps de se marier."]),
R(9228604,"Gnocchis végétaliens à la citrouille faits maison !",
"Des gnocchis végétaliens à la citrouille faits maison, moelleux et à tomber !",
"8 portions","1 portion",
["1 citrouille à tarte de 3 livres ou 2 tasses de purée de citrouille","sel + poivre pour saupoudrer la citrouille","3-3 ¼ tasses de farine de blé entier à pâtisserie","1 cuillère à café de sel de mer","½ cuillère à café de sauge moulue","⅛ cuillère à café de muscade moulue",["Sauce végétalienne « beurre » à la sauge","1 tasse de noix de cajou crues"],["Sauce végétalienne « beurre » à la sauge","¾ tasse d'eau chaude"],["Sauce végétalienne « beurre » à la sauge","2 gousses d'ail"],["Sauce végétalienne « beurre » à la sauge","½ cuillère à café de sauge moulue"],["Sauce végétalienne « beurre » à la sauge","sel + poivre au goût"],["Ou utilisez une autre sauce","sauce tomate ou sauce marinara de votre choix"],["Ou utilisez une autre sauce","sauce Alfredo"],["Ou utilisez une autre sauce","sauce bolognaise au chou-fleur"],["Pour la garniture","parmesan végétalien"],["Pour la garniture","feuilles de sauge fraîche, idéales avec la sauce au beurre"],["Pour la garniture","feuilles de basilic frais, idéales avec la sauce tomate"],["Pour la garniture","persil frais, idéal avec la sauce Alfredo"]],
[["Pour la purée de citrouille","Préchauffez votre four à 400 degrés en mode convection et garnissez une plaque de cuisson de papier parchemin."],["Pour la purée de citrouille","Coupez la citrouille en deux ou en trois et retirez les graines. Placez la citrouille côté peau vers le bas sur la plaque. Saupoudrez de sel et de poivre et faites rôtir jusqu'à ce qu'une fourchette perce facilement la chair, environ 40 minutes, puis sortez du four."],["Pour la purée de citrouille","Retirez la chair de la citrouille de sa peau, transférez-la dans un robot culinaire ou un mélangeur et mixez jusqu'à consistance très lisse. Procédez par lots au besoin. Mesurez 2 tasses de purée et mettez-les de côté pour préparer les gnocchis."],["Pour les gnocchis végétaliens à la citrouille","Dans un grand bol, mettez 2 tasses de purée de citrouille, 3 tasses de farine et les assaisonnements. Mélangez, puis transférez sur un grand plan de travail fariné."],["Pour les gnocchis végétaliens à la citrouille","Pétrissez la pâte à la main en ajoutant au besoin un peu de farine sur le plan de travail et sur vos mains pour éviter qu'elle colle. Utilisez le moins de farine possible pour éviter que la pâte colle, sans en ajouter trop. La pâte doit être un peu collante, c'est normal. Veillez à ne pas ajouter trop de farine, sinon les gnocchis ne seront pas moelleux."],["Pour les gnocchis végétaliens à la citrouille","Utilisez un rouleau à pâtisserie pour abaisser la pâte à environ un demi-pouce d'épaisseur."],["Pour les gnocchis végétaliens à la citrouille","Saupoudrez ensuite un couteau bien aiguisé ou un coupe-pizza de farine et coupez la pâte en bandes de 1 pouce. Coupez ensuite chaque bande en morceaux d'environ un demi-pouce pour obtenir un quadrillage. Saupoudrez les morceaux d'un peu plus de farine au besoin."],["Pour les gnocchis végétaliens à la citrouille","Facultatif : utilisez une planche à gnocchis farinée ou une grosse fourchette pour presser et rouler délicatement chaque gnocchi afin de former des rainures. Farinez de nouveau la planche ou la fourchette pour éviter que les gnocchis collent."],["Pour les gnocchis végétaliens à la citrouille","Placez les gnocchis préparés en une seule couche sur une plaque tapissée de papier parchemin. Si vous les faites cuire dans les 2 heures, vous pouvez les laisser à température ambiante. Sinon, suivez les instructions de conservation dans les notes ci-dessous."],["Pour cuire les gnocchis","Cette recette donne une grande quantité ; vous pouvez en congeler une partie et en faire cuire une partie tout de suite."],["Pour cuire les gnocchis","Pour la cuisson, portez à ébullition une grande casserole d'eau généreusement salée. Plongez ensuite les gnocchis dans l'eau bouillante, par lots pour éviter de surcharger la casserole. Faites bouillir jusqu'à ce qu'ils soient tendres et qu'ils remontent à la surface, environ 5-10 minutes. REMARQUE : le temps de cuisson varie selon la quantité dans la casserole, la farine utilisée et selon que la purée de citrouille est maison ou en conserve."],["Pour cuire les gnocchis","Retirez les gnocchis à l'aide d'une écumoire et placez-les dans un bol de service. Répétez avec les gnocchis restants jusqu'à avoir cuit la quantité désirée. Servez avec votre sauce préférée et les garnitures."],["Pour la sauce végétalienne « beurre » à la sauge","Mettez tous les ingrédients dans un mélangeur haute vitesse et mixez jusqu'à consistance lisse. Servez sur les gnocchis et garnissez de sauge fraîche."]],
["Ne travaillez pas trop la pâte . Il ne faut pas trop la pétrir, sinon les gnocchis seront plus fermes, et ils sont meilleurs lorsqu'ils sont moelleux. Travaillez-la environ 1-2 minutes, pas plus. N'exagérez pas avec la farine . Ajoutez-en juste assez pour que la pâte ne colle pas à vos mains et au plan de travail, mais pas trop, sinon les gnocchis seront durs. Un peu de collant, ce n'est pas grave. Une citrouille à tarte de 3 lb donne environ 2 tasses de purée de citrouille, soit ce dont cette recette a besoin. S'il vous en reste, réfrigérez-la ou congelez-la pour une autre recette. N'utilisez que 2 tasses pour cette recette , ou augmentez la farine pour compenser la différence si vous souhaitez en utiliser davantage. Gardez de la farine à portée de main pendant que vous travaillez . Vous en aurez besoin pour saupoudrer le plan de travail, vos mains, le rouleau, le couteau, la planche à gnocchis, etc. Veillez à garder vos gnocchis en une seule couche une fois préparés pour éviter qu'ils collent les uns aux autres. Pour gagner du temps , vous pouvez utiliser 2 tasses de purée de citrouille en conserve et omettre la cuisson de la citrouille au four, avec des résultats similaires. Si vous n'avez pas de planche à gnocchis ou ne souhaitez pas faire les rainures, vous pouvez omettre cette étape. Les rainures sont purement esthétiques et n'affectent ni le résultat ni la saveur du plat. Une fois vos gnocchis préparés (mais non cuits), vous pouvez les laisser à température ambiante jusqu'à 2 heures en une seule couche. Ou réfrigérez-les 1-2 jours si vous préparez à l'avance. Congelez les gnocchis crus en une seule couche pendant quelques heures, jusqu'à ce qu'ils soient fermes. Transférez-les ensuite dans un contenant hermétique ou un sac à fermeture zip et gardez-les congelés jusqu'à 3 mois. Faites-les cuire directement congelés, NE LES DÉCONGELEZ PAS . Les gnocchis à la citrouille cuisent un peu plus longtemps que ceux à la pomme de terre . Ils ne sont pas nécessairement prêts dès qu'ils remontent à la surface. Vérifiez la tendreté vers la marque des 5 minutes et poursuivez la cuisson jusqu'à ce qu'ils soient moelleux. ***L'information nutritionnelle représente ⅛ des gnocchis à la citrouille avec ⅛ de la sauce rapide végétalienne « beurre » à la sauge. Si vous utilisez une autre sauce, l'information nutritionnelle variera. Les restes de gnocchis cuits se conservent au réfrigérateur 2-3 jours."]),
R(9228909,"Côtes de maïs à la friteuse à air chaud",
"Des côtes de maïs collantes, sucrées et fumées à la friteuse à air chaud !! Cet excellent accompagnement est incroyablement délicieux, très simple à préparer et ne demande que DEUX ingrédients.",
"4 portions","1 portion",
["2 épis de maïs","3-4 cuillères à soupe de sauce barbecue"],
["Retirez les feuilles et utilisez un couteau bien aiguisé pour couper chaque épi en deux afin de faciliter le découpage en quartiers. Dressez ensuite chaque morceau à la verticale (le côté plat que vous venez de couper posé sur la planche à découper pour la stabilité) et coupez-le en deux dans le sens de la longueur. Placez ensuite ces morceaux côté cœur vers le bas et coupez-les de nouveau en deux. Vous obtiendrez 8 côtes de maïs par épi, soit 16 morceaux au total. L'objectif est de ne pas écraser les grains ; cette méthode de découpe est donc la plus efficace. Voir les photos du procédé ci-dessus pour plus de clarté.","Badigeonnez chaque côte de maïs de sauce barbecue et placez-les en une couche uniforme dans le panier de votre friteuse. Ce n'est pas grave si elles se chevauchent un peu. Faites cuire à la friteuse à air chaud à 380 °F/193 °C pendant 10-12 minutes et régalez-vous."],
["Choisissez du maïs frais , avec des grains plus gros. Les feuilles doivent être bien serrées, d'un vert vif, et ne pas jaunir ni se dessécher. Faites très attention en coupant votre maïs en « côtes »."]),
R(9228970,"Muffins végétaliens aux fraises",
"Des muffins végétaliens aux fraises moelleux, légèrement sucrés, sains et sans gluten.",
"12 muffins","1 portion",
["1 tasse de lait de soja (ou de lait d'amande)","1 cuillère à café de vinaigre de cidre de pomme (ou de jus de citron)","1/3 tasse de compote de pommes non sucrée","2 cuillères à café d'extrait de vanille pur","270 grammes de farine d'avoine (environ 3 tasses, versée à la cuillère + nivelée)","1/3 tasse de sucre de coco non raffiné","2 cuillères à café de poudre à pâte","1 tasse de fraises en dés"],
["Préchauffez votre four à 350 ℉/176 ℃ et graissez un moule à muffins ou garnissez-le de caissettes en papier parchemin, en quantité suffisante pour 12 muffins.","Mélangez le lait de soja et le vinaigre de cidre de pomme dans un grand bol et laissez reposer 5 minutes pour que le lait caille et épaississe et devienne votre babeurre végétalien.","Une fois le lait caillé, ajoutez la compote de pommes et la vanille dans le même bol et mélangez. Ajoutez ensuite tous les ingrédients secs : la farine, le sucre, la poudre à pâte, et mélangez jusqu'à ce que le tout soit combiné. Enfin, incorporez délicatement les fraises en dés.","Répartissez la pâte à muffins entre vos 12 moules et faites cuire dans votre four préchauffé 18-22 minutes, ou jusqu'à ce qu'un cure-dent inséré au centre en ressorte propre.","Laissez reposer les muffins 10 minutes avant de les transférer sur une grille pour qu'ils continuent de refroidir."]),
R(9229405,"Courgettes au citron à la friteuse à air chaud",
"Ces délicieuses courgettes au citron sont faciles à préparer, avec seulement 5 ingrédients ! Un accompagnement super simple, délicieux et parfait, prêt en un rien de temps.",
"3 portions","1 portion",
["3 courgettes moyennes coupées en tranches de ⅛ pouce (environ 6 tasses)","2 cuillères à soupe de jus de citron, environ un citron moyen","½ cuillère à café de poudre d'ail","½ cuillère à café d'origan séché","¼ cuillère à café de sel de mer ou au goût"],
["Coupez vos courgettes en tranches d'environ 1/8 de pouce d'épaisseur et mettez-les dans un bol.","Mélangez ensuite tous les autres ingrédients dans un petit bol et versez le mélange sur les tranches de courgette. Mélangez bien pour vous assurer que chaque morceau est enrobé, en séparant les tranches avec vos mains au fur et à mesure.","Placez les courgettes dans votre panier et faites cuire à la friteuse à air chaud à 400 degrés F pendant 20-25 minutes, jusqu'à ce qu'elles soient dorées. Secouez doucement votre panier ou remuez les courgettes environ toutes les 5 minutes pour une cuisson uniforme."],
["Tranchez vos courgettes de la façon la plus uniforme possible pour une cuisson uniforme. Secouez votre panier , ou remuez délicatement, environ toutes les 5 minutes pendant la cuisson. Cela assure une cuisson uniforme et évite que les courgettes collent au panier. Essayez différents mélanges d'épices pour varier à chaque fois. Voir mes suggestions ci-dessus ! Les restes se conservent au réfrigérateur dans un contenant fermé 3-4 jours."]),
R(9229801,"Mini-carottes à l'érable et à l'ail à la friteuse à air chaud",
"Une variante délicieuse de la recette au miel et à l'ail : ces mini-carottes à l'érable et à l'ail sont pleines de saveur !",
"4 portions","1 portion",
["1 paquet de 12 onces de mini-carottes","2 gousses d'ail émincées","1 cuillère à soupe de sirop d'érable","1 cuillère à soupe de tamari ou de sauce soja","1 cuillère à soupe d'huile d'avocat ou de beurre fondu ou de margarine (facultatif)*","persil frais ou coriandre fraîche facultatif, pour la garniture"],
["Mettez les carottes et les autres ingrédients (sauf le persil) dans un petit bol. Mélangez jusqu'à ce que les carottes soient uniformément enrobées.","Utilisez ensuite une écumoire pour placer vos carottes dans le panier de votre friteuse à air chaud. (Ne versez pas tout d'un coup.) Disposez-les en une seule couche et faites cuire à la friteuse à air chaud à 400 degrés F pendant 12-16 minutes. Secouez ou remuez les carottes environ toutes les 5 minutes.","Une fois les carottes cuites à votre goût, retirez-les du panier et enrobez-les du reste du glaçage si vous le souhaitez. Servez ensuite avec des herbes fraîches et régalez-vous."],
["* Pour une version sans huile , omettez l'huile ou le beurre et utilisez à la place une cuillère à soupe de bouillon. La taille des carottes et le modèle de friteuse détermineront le temps de cuisson . Vérifiez souvent vos carottes vers la fin de la cuisson. Les restes se conservent au réfrigérateur 3-4 jours, mais sont meilleurs fraîchement préparés."]),
R(9231462,"Crêpes épaisses saines aux graines de pavot et au citron [végétaliennes]",
"Ces pancakes végétaliens sains aux graines de pavot et au citron sont légèrement acidulés, avec une belle texture grâce aux graines de pavot réparties partout.",
"12 pancakes de 4 po","1 pancake",
[["Ingrédients humides","1.5 tasse de lait de soja"],["Ingrédients humides","4 cuillères à soupe de jus de citron, d'environ 1 citron"],["Ingrédients humides","1 cuillère à soupe de zeste de citron, d'environ 1 citron"],["Ingrédients humides","2 cuillères à café d'extrait de vanille pur"],["Ingrédients secs","180 grammes de farine d'avoine, environ 2 tasses"],["Ingrédients secs","3 cuillères à soupe de graines de pavot"],["Ingrédients secs","2 cuillères à café de poudre à pâte"],["Ingrédients secs","2 cuillères à soupe de graines de lin moulues"],["Garnitures facultatives","sirop d'érable"],["Garnitures facultatives","baies fraîches"]],
["Mettez le lait de soja, le jus de citron et le zeste de citron dans un petit bol et laissez reposer 5 minutes pour qu'il épaississe et caille.","Dans un grand bol, mettez tous les ingrédients secs et fouettez pour les combiner. Ajoutez ensuite le lait caillé/épaissi et la vanille et mélangez jusqu'à ce que le tout soit combiné. Laissez reposer la pâte à pancakes 5 minutes pendant que vous préchauffez votre plaque de cuisson antiadhésive.","Versez la pâte à la louche sur votre plaque pour obtenir des pancakes d'environ 4 pouces de diamètre, en les étalant délicatement en versant.","Faites cuire les pancakes 4-5 minutes, puis retournez-les et faites-les cuire encore 3-4 minutes jusqu'à ce que les bords soient dorés. Servez avec les garnitures de votre choix et régalez-vous."],
["Utilisez de la poudre à pâte fraîche et active . Une poudre à pâte ouverte depuis plusieurs mois dans le garde-manger peut commencer à perdre son efficacité. Inutile de trop mélanger votre pâte à pancakes . S'il reste quelques grumeaux, ce n'est pas grave. Mélangez simplement jusqu'à ce que le tout soit combiné et qu'il ne reste plus de traces de farine. Préchauffez votre poêle ou plaque de cuisson. Elle doit être chaude avant de verser la pâte pour éviter que ça colle et pour une cuisson uniforme. Utilisez un feu moyen pour cuire vos pancakes . Même si votre poêle doit être chaude, cela ne signifie pas qu'il faut utiliser un feu vif. Cela peut donner une cuisson inégale, avec l'extérieur croustillant et l'intérieur mou. Retournez vos pancakes UNE SEULE FOIS . Lorsque les bords sont dorés et qu'ils ont cuit au moins 3-4 minutes, retournez-les. Les retourner trop souvent peut les faire s'affaisser et donner une texture plus dense. La pâte épaissira en reposant ; si elle devient trop épaisse entre les fournées de pancakes, ajoutez 1-2 cuillères à soupe de lait végétal dans le bol. Les restes se conservent au réfrigérateur 2-3 jours ou se congèlent jusqu'à 3 mois."]),
R(9235323,"Burritos au jacquier BBQ [burritos végétaliens]",
"Les burritos végétaliens passent au niveau supérieur avec du jacquier BBQ fumé, acidulé et incroyablement savoureux !",
"6 portions","1 portion",
["1 boîte de 20 onces de jacquier vert jeune dans la saumure ou l'eau, PAS dans le sirop",["Pour la sauce","¼ tasse de ketchup"],["Pour la sauce","¼ tasse de vinaigre de cidre de pomme"],["Pour la sauce","2 cuillères à soupe d'eau"],["Pour la sauce","1 cuillère à soupe de sauce soja ou de tamari si vous évitez le gluten"],["Pour la sauce","1 cuillère à soupe de sirop d'érable"],["Pour la sauce","1 cuillère à soupe de moutarde jaune"],["Pour la sauce","1 cuillère à café de paprika fumé ou de fumée liquide"],["Pour la sauce","1 cuillère à café de poudre d'ail"],["Pour la sauce","1 cuillère à café de poudre d'oignon"],["Pour les burritos végétaliens","tortillas de votre choix, sans gluten si vous préférez"],["Pour les burritos végétaliens","riz cuit"],["Pour les burritos végétaliens","haricots noirs"],["Pour les burritos végétaliens","maïs"],["Pour les burritos végétaliens","tomates en dés"],["Pour les burritos végétaliens","olives noires"],["Pour les burritos végétaliens","jalapeño tranché"],["Pour les burritos végétaliens","coriandre fraîche"],["Pour les burritos végétaliens","salsa"],["Pour les burritos végétaliens","guacamole"],["Pour les burritos végétaliens","crème de cajou"]],
["Égouttez et rincez très bien votre jacquier pour éliminer le goût de la saumure. Utilisez ensuite vos mains (ou deux fourchettes sur une planche à découper) pour effilocher les morceaux de jacquier. Mettez-les dans un petit bol et réservez.","Dans un autre petit bol, mettez TOUS les ingrédients de la sauce et fouettez pour les combiner. Versez ensuite sur le jacquier et mélangez pour l'enrober uniformément. Choisissez une méthode de cuisson ci-dessous.",["Instructions au four","Préchauffez le four à 425 degrés F et garnissez une plaque de cuisson de papier parchemin. Disposez le jacquier enrobé sur la plaque et faites cuire 20 minutes, en mélangeant une fois à mi-cuisson. Sortez du four."],["Instructions à l'Instant Pot","Mettez le jacquier enrobé dans votre Instant Pot et faites cuire à haute pression 5 minutes. Laissez ensuite la pression retomber naturellement 10 minutes. Si elle n'est pas complètement retombée après 10 minutes, relâchez rapidement le reste de la pression et ouvrez le couvercle lorsque cela est sécuritaire."],["Instructions sur la cuisinière","Mettez le jacquier enrobé dans une poêle moyenne et faites cuire à feu moyen-vif en remuant de temps en temps, jusqu'à ce que la sauce soit presque entièrement absorbée. Cela prendra environ 10-12 minutes."],["Assemblez vos burritos végétaliens","Assemblez votre burrito au jacquier avec les garnitures désirées et la tortilla de votre choix, ou préparez-en un bol de burrito au jacquier sur un lit de laitue avec les garnitures désirées par-dessus."]],
["Ne remplissez pas trop vos burritos végétaliens, sinon ils seront difficiles à fermer et à tenir et pourraient se défaire. Moins, c'est mieux ! Conservez les garnitures restantes dans des contenants séparés au réfrigérateur 3-4 jours et assemblez votre burrito au jacquier juste avant de manger pour éviter que la tortilla ramollisse."]),
]
save(11,recs)
